188	      <li><a href="#contact" data-nav-link>Contact</a></li>
189	    </ul>
190	  </nav>
191	  <main id="main" tabindex="-1">
192	    <section id="home" aria-labelledby="home-heading">
193	      <h1 id="home-heading">My Page</h1>
194	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
195	    </section>
196	
197	    <section id="about" aria-labelledby="about-heading">
