260	  <script>
261	    const yearEl = document.getElementById('year');
262	    if (yearEl) yearEl.textContent = String(new Date().getFullYear());
263	
264	    const themeToggle = document.getElementById('theme-toggle');
265	    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
266	
267	    const currentTheme = () =>
268	      document.documentElement.dataset.theme || (prefersDark.matches ? 'dark' : 'light');
269	
270	    const updateToggleLabel = () => {
271	      themeToggle.textContent = currentTheme() === 'dark' ? '☀️' : '🌙';
272	    };
273	
274	    updateToggleLabel();
275	
276	    themeToggle.addEventListener('click', () => {
277	      const next = currentTheme() === 'dark' ? 'light' : 'dark';
278	      document.documentElement.dataset.theme = next;
279	      localStorage.setItem('theme', next);
280	      updateToggleLabel();
281	    });
282	
283	    const navLinks = document.querySelectorAll('[data-nav-link]');
284	    const sections = [...navLinks]
285	      .map(link => document.querySelector(link.getAttribute('href')))
286	      .filter(Boolean);
287	
288	    const setActive = (id) => {
289	      navLinks.forEach(link => {
290	        if (link.getAttribute('href') === `#${id}`) {
291	          link.setAttribute('aria-current', 'page');
292	        } else {
293	          link.removeAttribute('aria-current');
294	        }
295	      });
296	    };
297	
298	    setActive(sections[0]?.id);
299	
300	    navLinks.forEach(link => {
301	      link.addEventListener('click', () => setActive(link.getAttribute('href').slice(1)));
302	    });
303	
304	    if ('IntersectionObserver' in window) {
305	      const observer = new IntersectionObserver((entries) => {
306	        const visible = entries
307	          .filter(entry => entry.isIntersecting)
308	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
309	        if (visible) setActive(visible.target.id);
310	      }, { rootMargin: '-40% 0px -50% 0px' });
311	      sections.forEach(section => section && observer.observe(section));
312	    }
313	  </script>
